{
  "title": "Обговорення AI та інші теми",
  "claims": [
    {
      "topic": "AI як інструмент",
      "text": "AI за своєю суттю не може бути розумною апріорі, а лише набором інструментів і готових прикладів вирішення задач.",
      "evidence": [1]
    },
    {
      "topic": "Потреба в розумному AI",
      "text": "Нікому не потрібно, щоб AI був розумним, бо люди самі не знають, як це робити.",
      "evidence": [2]
    },
    {
      "topic": "Тестування старих моделей AI",
      "text": "Автор хоче протестувати AI 2022‑2023 років сучасним інструментарієм типу opencode, передбачаючи, що старі моделі не впораються через маленьке контекстне вікно.",
      "evidence": [3]
    },
    {
      "topic": "Вплив інструментів на продуктивність моделей",
      "text": "InstinctGPT порівнював 3 B і GPT‑3 175 B з зовнішнім runtime і інструментами; інструментарій дає великий приріст, але не компенсує нестачу базових здібностей моделі.",
      "evidence": [8]
    },
    {
      "topic": "Метрики та тренування сучасних моделей",
      "text": "У ChatGPT 3 реальна метрика – активні параметри, а не лише 175 B; старі моделі навчалися без розуміння цілі, тоді як сучасні намагаються отримати максимум з меншою кількістю параметрів і інколи тренуються під конкретні завдання.",
      "evidence": [14]
    },
    {
      "topic": "Джерело зовнішньої інформації",
      "text": "Посилання, подане користувачем P4, має джерело, зазначене як @fionalt.",
      "evidence": [16, 17]
    },
    {
      "topic": "Відчуття погоди",
      "text": "Автор відчуває в повітрі атмосферу, схожу на дощ, хоча температура нагадує лаву.",
      "evidence": [20]
    },
    {
      "topic": "Температурна аномалія",
      "text": "Сьогодні було особливо жарко.",
      "evidence": [21]
    },
    {
      "topic": "Оплата за обкладинки дипломів",
      "text": "Дехто стягує гроші за обкладинки дипломів: 650 грн у Богдана, 47 грн у іншого, 30 грн у ще одного.",
      "evidence": [23, 24, 25]
    },
    {
      "topic": "Корисність обкладинки диплома",
      "text": "Обкладинка диплома вважається марною: її будуть переглядати лише тричі в житті (при отриманні, фотографуванні та перекладі документів).",
      "evidence": [29]
    }
  ]
}
